//! Durable per-repository protocol state and the irreversible
//! **decision-required** fence.
//!
//! The frozen 139 gate row is not changed: realm, the one-way
//! `decision_required` fence and the monotone `roots_revision` live in the
//! separate `ref_store_core_protocol_repos` table (migration 144, generated by
//! the roots owner). This module owns only the *common* parts of that table:
//!
//! * an explicit, unserved provisioning step ([`PgDecisionProtocol::provision`])
//!   that binds the protocol realm to the current core gate of an isolated
//!   `provisioning`/`gitfs`/`stable` repository with no Pando authority. No
//!   global "ready" check is relaxed and nothing becomes serve-ready;
//! * a one-way fence enable ([`PgDecisionProtocol::enable_decisions`]) that no
//!   later writer can revert (the DDL trigger refuses `true -> false`);
//! * in-transaction helpers ([`refuse_legacy_fresh_write`], [`fence_probe`],
//!   [`lock_and_enforce`], [`enable_fence`]) used by the legacy metadata/A4
//!   commit paths and by the authorized decision commit path so **both** read
//!   the same row in the same place of the lock order.
//!
//! Lock order (frozen for every path): migration-138 operation prefix ->
//! repository row -> pack tenant usage -> pack repository usage -> core gate
//! `FOR UPDATE` -> `ref_store_core_protocol_repos` -> root/decision rows. The
//! protocol row is therefore always taken **after** the gate (never before it),
//! exactly like the roots adapter, so enabling the fence (which happens while
//! the gate is held) can never deadlock against a roots register that already
//! holds the same gate.
//!
//! What the fence does: after a repository has entered the decision protocol,
//! a *fresh* legacy metadata-only or A4 pack commit is refused with the same
//! typed `Unsupported` refusal the older pack-mode fence uses. An already
//! durable 138 operation terminal keeps replaying byte-for-byte: replay runs
//! before this check and stays historical data (no re-authorization, no
//! refund, no new write).
use crate::ref_store::contract::RefStoreError;
use crate::ref_store::core::contract::CoreGate;
use crate::ref_store::core::sql::gate_from_row;
use crate::ref_store::core::types::GitObjectFormat;
use crate::ref_store::pg;
use crate::ref_store::tx::{begin_bounded, commit_bounded};
use tokio::time::Instant;
use tokio_postgres::{Client, Row, Transaction};
use uuid::Uuid;

const REALM_COLUMNS: &str =
    "tenant_id,object_format,history_incarnation,authority_epoch,group_epoch,decision_required,roots_revision";

/// Realm + protocol state of one repository, read from
/// `ref_store_core_protocol_repos`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ProtocolRepoRealm {
    repository_id: Uuid,
    tenant_id: Uuid,
    object_format: GitObjectFormat,
    history_incarnation: Uuid,
    authority_epoch: i64,
    group_epoch: i64,
    decision_required: bool,
    roots_revision: i64,
}

impl ProtocolRepoRealm {
    fn from_row(repository_id: Uuid, row: &Row) -> Result<Self, RefStoreError> {
        let tenant_id: Uuid = row.get(0);
        let object_format: String = row.get(1);
        let history_incarnation: Uuid = row.get(2);
        let authority_epoch: i64 = row.get(3);
        let group_epoch: i64 = row.get(4);
        let decision_required: bool = row.get(5);
        let roots_revision: i64 = row.get(6);
        if tenant_id.is_nil() || history_incarnation.is_nil() {
            return Err(RefStoreError::Database("protocol realm has a nil id".into()));
        }
        if authority_epoch <= 0 || group_epoch <= 0 || roots_revision < 0 {
            return Err(RefStoreError::Database("protocol realm counters are out of range".into()));
        }
        Ok(Self {
            repository_id,
            tenant_id,
            object_format: GitObjectFormat::parse(&object_format)?,
            history_incarnation,
            authority_epoch,
            group_epoch,
            decision_required,
            roots_revision,
        })
    }

    pub fn repository_id(&self) -> Uuid {
        self.repository_id
    }
    pub fn tenant_id(&self) -> Uuid {
        self.tenant_id
    }
    pub fn object_format(&self) -> GitObjectFormat {
        self.object_format
    }
    pub fn history_incarnation(&self) -> Uuid {
        self.history_incarnation
    }
    pub fn authority_epoch(&self) -> i64 {
        self.authority_epoch
    }
    pub fn group_epoch(&self) -> i64 {
        self.group_epoch
    }
    /// One-way irreversible fence: once `true`, only the authorized decision
    /// commit path may write refs/revision for this repository.
    pub fn decision_required(&self) -> bool {
        self.decision_required
    }
    pub fn roots_revision(&self) -> i64 {
        self.roots_revision
    }
}

/// The exact realm a caller expects. Constructed from the plan scope or from a
/// locked gate; the protocol row must match every field.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct RealmExpectation {
    repository_id: Uuid,
    tenant_id: Uuid,
    object_format: GitObjectFormat,
    history_incarnation: Uuid,
    authority_epoch: i64,
    group_epoch: i64,
}

impl RealmExpectation {
    pub fn new(
        repository_id: Uuid,
        tenant_id: Uuid,
        object_format: GitObjectFormat,
        history_incarnation: Uuid,
        authority_epoch: i64,
        group_epoch: i64,
    ) -> Result<Self, RefStoreError> {
        if repository_id.is_nil() || tenant_id.is_nil() || history_incarnation.is_nil() {
            return Err(RefStoreError::InvalidIdentity("protocol realm ids must be non-nil".into()));
        }
        if authority_epoch <= 0 || group_epoch <= 0 {
            return Err(RefStoreError::InvalidIdentity("protocol realm epoch must be positive".into()));
        }
        Ok(Self { repository_id, tenant_id, object_format, history_incarnation, authority_epoch, group_epoch })
    }

    /// Exact realm of one already locked core gate (same repository id).
    pub fn from_gate(gate: &CoreGate) -> Self {
        Self {
            repository_id: gate.repository_id(),
            tenant_id: gate.tenant_id(),
            object_format: gate.object_format(),
            history_incarnation: gate.history_incarnation(),
            authority_epoch: gate.authority_epoch(),
            group_epoch: gate.group_epoch(),
        }
    }

    pub fn repository_id(&self) -> Uuid {
        self.repository_id
    }
    pub fn tenant_id(&self) -> Uuid {
        self.tenant_id
    }
    pub fn object_format(&self) -> GitObjectFormat {
        self.object_format
    }
    pub fn history_incarnation(&self) -> Uuid {
        self.history_incarnation
    }
    pub fn authority_epoch(&self) -> i64 {
        self.authority_epoch
    }
    pub fn group_epoch(&self) -> i64 {
        self.group_epoch
    }

    fn matches(&self, realm: &ProtocolRepoRealm) -> bool {
        realm.repository_id == self.repository_id
            && realm.tenant_id == self.tenant_id
            && realm.object_format == self.object_format
            && realm.history_incarnation == self.history_incarnation
            && realm.authority_epoch == self.authority_epoch
            && realm.group_epoch == self.group_epoch
    }

    /// Type refusal used by every path that finds a different realm.
    fn mismatch(&self) -> RefStoreError {
        RefStoreError::Unsupported("protocol realm does not match the locked core gate/plan realm")
    }
}

/// Result of probing the fence inside an owned transaction.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DecisionFence {
    /// No protocol row: this repository never entered the decision protocol, so
    /// the legacy metadata/A4 paths are unchanged (old regression tests keep
    /// working on such repositories).
    Unprovisioned,
    /// Provisioned (roots and/or decisions) but no decision-gated commit has
    /// taken the irreversible fence yet.
    Provisioned,
    /// Irreversible fence: fresh legacy metadata/A4 writes are refused.
    Required,
}

impl DecisionFence {
    /// True only for the one-way `decision_required = true` state.
    pub fn blocks_legacy_fresh_write(self) -> bool {
        matches!(self, Self::Required)
    }
}

/// Probe the fence with a `FOR SHARE` row lock (never creates the row).
///
/// Callers already hold the core gate `FOR UPDATE`, and the fence is only ever
/// enabled while that same gate is held, so this read is serialized with an
/// in-flight enable without taking a second lock order.
pub(crate) async fn fence_probe(tx: &Transaction<'_>, repository_id: Uuid) -> Result<DecisionFence, RefStoreError> {
    let row = tx
        .query_opt(
            "SELECT decision_required FROM ref_store_core_protocol_repos WHERE repository_id=$1 FOR SHARE",
            &[&repository_id],
        )
        .await
        .map_err(pg::db_error)?;
    Ok(match row {
        None => DecisionFence::Unprovisioned,
        Some(row) if row.get::<_, bool>(0) => DecisionFence::Required,
        Some(_) => DecisionFence::Provisioned,
    })
}

/// Refusal used by a legacy fresh metadata-only / A4 write inside its own
/// transaction. Call it **after** the exact 138 terminal replay and **before**
/// the first ref/gate-revision write; replay therefore keeps working on a
/// fenced repository while new legacy writes do not.
pub(crate) async fn refuse_legacy_fresh_write(tx: &Transaction<'_>, repository_id: Uuid) -> Result<(), RefStoreError> {
    if fence_probe(tx, repository_id).await?.blocks_legacy_fresh_write() {
        return Err(RefStoreError::Unsupported(
            "repository has the irreversible decision-required fence; fresh legacy metadata/A4 ref writes are refused",
        ));
    }
    Ok(())
}

/// Lock the protocol row `FOR UPDATE`, require an exact realm match and return
/// it. A missing row is the typed "not provisioned" refusal: the decision path
/// never creates protocol state implicitly.
pub(crate) async fn lock_and_enforce(
    tx: &Transaction<'_>,
    expectation: &RealmExpectation,
) -> Result<ProtocolRepoRealm, RefStoreError> {
    let row = tx
        .query_opt(
            &format!("SELECT {REALM_COLUMNS} FROM ref_store_core_protocol_repos WHERE repository_id=$1 FOR UPDATE"),
            &[&expectation.repository_id()],
        )
        .await
        .map_err(pg::db_error)?;
    let Some(row) = row else {
        return Err(RefStoreError::Unsupported(
            "repository is not provisioned in the decision protocol; explicit provisioning is required",
        ));
    };
    let realm = ProtocolRepoRealm::from_row(expectation.repository_id(), &row)?;
    if !expectation.matches(&realm) {
        return Err(expectation.mismatch());
    }
    Ok(realm)
}

/// One-way fence enable inside an already locked protocol row (`true` can never
/// become `false`; the DDL trigger enforces that independently).
pub(crate) async fn enable_fence(tx: &Transaction<'_>, repository_id: Uuid) -> Result<(), RefStoreError> {
    tx.execute(
        "UPDATE ref_store_core_protocol_repos SET decision_required=TRUE
         WHERE repository_id=$1 AND decision_required=FALSE",
        &[&repository_id],
    )
    .await
    .map_err(pg::db_error)?;
    Ok(())
}

/// Independent read-only adapter over `ref_store_core_protocol_repos`.
#[derive(Clone, Copy, Debug)]
pub struct PgDecisionProtocol;

impl PgDecisionProtocol {
    pub const fn new() -> Self {
        Self
    }

    /// Read-only realm lookup. `None` means the repository never entered the
    /// protocol (the legacy paths stay unchanged). No authority is implied.
    pub async fn read(
        &self,
        client: &mut Client,
        repository_id: Uuid,
        deadline: Instant,
    ) -> Result<Option<ProtocolRepoRealm>, RefStoreError> {
        if repository_id.is_nil() {
            return Err(RefStoreError::InvalidIdentity("protocol realm lookup id must be non-nil".into()));
        }
        let tx = begin_bounded(client, deadline).await?;
        let result = pg::before_deadline(deadline, async {
            pg::bound(&tx, deadline).await?;
            let row = tx
                .query_opt(
                    &format!("SELECT {REALM_COLUMNS} FROM ref_store_core_protocol_repos WHERE repository_id=$1"),
                    &[&repository_id],
                )
                .await
                .map_err(pg::db_error)?;
            row.as_ref().map(|row| ProtocolRepoRealm::from_row(repository_id, row)).transpose()
        })
        .await;
        let _ = tx.rollback().await;
        result
    }

    /// Read-only fence probe in its own short transaction.
    pub async fn read_fence(
        &self,
        client: &mut Client,
        repository_id: Uuid,
        deadline: Instant,
    ) -> Result<DecisionFence, RefStoreError> {
        if repository_id.is_nil() {
            return Err(RefStoreError::InvalidIdentity("protocol fence lookup id must be non-nil".into()));
        }
        let tx = begin_bounded(client, deadline).await?;
        let result = pg::before_deadline(deadline, async {
            pg::bound(&tx, deadline).await?;
            fence_probe(&tx, repository_id).await
        })
        .await;
        let _ = tx.rollback().await;
        result
    }

    /// Explicit unserved provisioning: bind the protocol realm to the current
    /// core gate of an isolated `provisioning`/`gitfs`/`stable` repository with
    /// no Pando authority and no legacy refs. Idempotent for an identical realm;
    /// a different realm is a typed conflict. The fence stays off so a
    /// repository may be provisioned for roots only.
    pub async fn provision(
        &self,
        client: &mut Client,
        expectation: &RealmExpectation,
        deadline: Instant,
    ) -> Result<ProtocolRepoRealm, RefStoreError> {
        let tx = begin_bounded(client, deadline).await?;
        let result = pg::before_deadline(deadline, self.provision_inner(&tx, expectation, false, deadline)).await;
        match result {
            Ok(realm) => {
                commit_bounded(tx, deadline, expectation.repository_id(), None).await?;
                Ok(realm)
            }
            Err(error) => {
                let _ = tx.rollback().await;
                Err(error)
            }
        }
    }

    /// Provision (if needed) **and** enable the irreversible decision fence in
    /// the same short transaction that installs the decision protocol state.
    /// After this commits, a fresh legacy metadata/A4 write for the repository
    /// is refused while exact terminal replay keeps working.
    pub async fn enable_decisions(
        &self,
        client: &mut Client,
        expectation: &RealmExpectation,
        deadline: Instant,
    ) -> Result<ProtocolRepoRealm, RefStoreError> {
        let tx = begin_bounded(client, deadline).await?;
        let result = pg::before_deadline(deadline, self.provision_inner(&tx, expectation, true, deadline)).await;
        match result {
            Ok(realm) => {
                commit_bounded(tx, deadline, expectation.repository_id(), None).await?;
                Ok(realm)
            }
            Err(error) => {
                let _ = tx.rollback().await;
                Err(error)
            }
        }
    }

    async fn provision_inner(
        &self,
        tx: &Transaction<'_>,
        expectation: &RealmExpectation,
        enable: bool,
        deadline: Instant,
    ) -> Result<ProtocolRepoRealm, RefStoreError> {
        // Transaction-local durability: never acknowledge a durable realm/fence
        // row under an external synchronous_commit=off policy.
        tx.execute("SET LOCAL synchronous_commit = 'on'", &[]).await.map_err(pg::db_error)?;
        pg::bound(tx, deadline).await?;
        // Repository authority: unchanged isolated unserved bootstrap state. No
        // global readiness relaxation is added here.
        let row = tx
            .query_opt(
                "SELECT r.owner_id,r.state,r.storage_backend,r.transition_state,
                        EXISTS(SELECT 1 FROM pando_repository_states s WHERE s.repository_id=r.id)
                 FROM repositories r WHERE r.id=$1 FOR SHARE",
                &[&expectation.repository_id()],
            )
            .await
            .map_err(pg::db_error)?
            .ok_or(RefStoreError::RepositoryNotFound)?;
        let owner: Uuid = row.get(0);
        let state: String = row.get(1);
        let backend: String = row.get(2);
        let transition: String = row.get(3);
        let pando: bool = row.get(4);
        if owner != expectation.tenant_id() {
            return Err(RefStoreError::RepositoryNotFound);
        }
        if state != "provisioning" || backend != "gitfs" || transition != "stable" || pando {
            return Err(RefStoreError::Unsupported(
                "protocol provisioning requires an isolated unserved core repository (provisioning/gitfs/stable, no pando authority)",
            ));
        }
        // Gate `FOR UPDATE` after the repository row: the protocol realm is a
        // copy of exactly this locked gate realm.
        let gate_row = tx
            .query_opt(
                "SELECT tenant_id,object_format,history_incarnation,authority_epoch,group_epoch,head_ref,revision
                 FROM ref_store_core_gates WHERE repository_id=$1 FOR UPDATE",
                &[&expectation.repository_id()],
            )
            .await
            .map_err(pg::db_error)?
            .ok_or(RefStoreError::Unsupported("protocol provisioning requires an existing core gate"))?;
        let gate = gate_from_row(expectation.repository_id(), &gate_row)?;
        if RealmExpectation::from_gate(&gate) != *expectation {
            return Err(expectation.mismatch());
        }
        tx.execute(
            "INSERT INTO ref_store_core_protocol_repos
                 (repository_id,tenant_id,object_format,history_incarnation,authority_epoch,group_epoch)
             VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT (repository_id) DO NOTHING",
            &[
                &expectation.repository_id(),
                &expectation.tenant_id(),
                &expectation.object_format().as_str(),
                &expectation.history_incarnation(),
                &expectation.authority_epoch(),
                &expectation.group_epoch(),
            ],
        )
        .await
        .map_err(pg::db_error)?;
        let row = tx
            .query_one(
                &format!("SELECT {REALM_COLUMNS} FROM ref_store_core_protocol_repos WHERE repository_id=$1 FOR UPDATE"),
                &[&expectation.repository_id()],
            )
            .await
            .map_err(pg::db_error)?;
        let realm = ProtocolRepoRealm::from_row(expectation.repository_id(), &row)?;
        if !expectation.matches(&realm) {
            return Err(expectation.mismatch());
        }
        if !enable {
            return Ok(realm);
        }
        if !realm.decision_required {
            enable_fence(tx, expectation.repository_id()).await?;
            return Ok(ProtocolRepoRealm { decision_required: true, ..realm });
        }
        Ok(realm)
    }
}

impl Default for PgDecisionProtocol {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn realm(decision_required: bool) -> ProtocolRepoRealm {
        ProtocolRepoRealm {
            repository_id: Uuid::from_bytes([1; 16]),
            tenant_id: Uuid::from_bytes([2; 16]),
            object_format: GitObjectFormat::Sha1,
            history_incarnation: Uuid::from_bytes([3; 16]),
            authority_epoch: 1,
            group_epoch: 1,
            decision_required,
            roots_revision: 0,
        }
    }

    fn expectation() -> RealmExpectation {
        RealmExpectation::new(
            Uuid::from_bytes([1; 16]),
            Uuid::from_bytes([2; 16]),
            GitObjectFormat::Sha1,
            Uuid::from_bytes([3; 16]),
            1,
            1,
        )
        .unwrap()
    }

    #[test]
    fn fence_only_blocks_fresh_legacy_writes_when_required() {
        assert!(!DecisionFence::Unprovisioned.blocks_legacy_fresh_write());
        assert!(!DecisionFence::Provisioned.blocks_legacy_fresh_write());
        assert!(DecisionFence::Required.blocks_legacy_fresh_write());
    }

    #[test]
    fn realm_expectation_binds_every_field() {
        let expected = expectation();
        assert!(expected.matches(&realm(false)));
        let mut other = realm(false);
        other.history_incarnation = Uuid::from_bytes([4; 16]);
        assert!(!expected.matches(&other));
        let mut other = realm(false);
        other.authority_epoch = 2;
        assert!(!expected.matches(&other));
        let nil = RealmExpectation::new(
            Uuid::nil(),
            Uuid::from_bytes([1; 16]),
            GitObjectFormat::Sha1,
            Uuid::from_bytes([2; 16]),
            1,
            1,
        );
        assert!(nil.is_err());
    }
}
